function clampPct(n){ n=Number(n); if(isNaN(n)) n=0; return Math.max(0, Math.min(100, n)); }
function buildStops(stops){
  return stops.map(function(s){ return s.color+' '+clampPct(s.pos)+'%'; }).join(', ');
}
function buildGradient(type, angle, stops){
  var body=buildStops(stops);
  if(type==='radial') return 'radial-gradient(circle, '+body+')';
  if(type==='conic') return 'conic-gradient(from '+(Number(angle)||0)+'deg, '+body+')';
  return 'linear-gradient('+(Number(angle)||0)+'deg, '+body+')';
}
function toBackground(css){ return 'background: '+css+';'; }
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { clampPct:clampPct, buildStops:buildStops, buildGradient:buildGradient, toBackground:toBackground };
}
if (typeof window !== 'undefined') {
  window.GradientForgePure = { clampPct:clampPct, buildStops:buildStops, buildGradient:buildGradient, toBackground:toBackground };
}
